  let src = `${location.origin}/chat/share?shared_id=${token}&from=${form}&auth=${beta}`;
  if (visibleAvatar) {
    src += '&visible_avatar=1';
  }
  if (locale) {
    src += `&locale=${locale}`;
  }
  return src;
}, [token, form, beta, visibleAvatar, locale]);
```

